266	/// Check if a creature has a "prevent damage, remove counter" replacement effect
267	/// (e.g., Unbreathing Horde). If so, prevent the damage and remove a +1/+1 counter.
268	/// Returns true if damage was prevented.
269	fn apply_prevent_damage_remove_counter(state: &mut GameState, target: ObjectId, registry: &CardRegistry) -> bool {
270	    let has_effect = state.has_continuous_effect(target, &|e| {
271	        match e {
272	            crate::types::ContinuousEffect::PreventDamageRemoveCounter { scope } => Some(scope),
273	            _ => None,
274	        }
275	    }, registry);
276	    if has_effect {
277	        let counter_count = state.get_object(target)
278	            .and_then(|o| o.counters.get(&crate::types::CounterType::PlusOnePlusOne).copied())
279	            .unwrap_or(0);
280	        if counter_count > 0 {
281	            if let Some(obj) = state.get_object_mut(target) {
282	                let entry = obj.counters.entry(crate::types::CounterType::PlusOnePlusOne).or_insert(0);
283	                *entry = entry.saturating_sub(1);
284	                if *entry == 0 {
285	                    obj.counters.remove(&crate::types::CounterType::PlusOnePlusOne);
286	                }
287	            }
288	            let name = state.get_object(target).map(|o| o.name.clone()).unwrap_or_default();
289	            state.log(crate::state::LogLevel::Event,
290	                format!("{}: damage prevented, removed a +1/+1 counter", name));
291	        }
292	        // Damage is always prevented even if no counters remain.
293	        true
294	    } else {
295	        false
296	    }
297	}
